def _builder_code_step(vars):
    _builder_response_guard_v1 = True
    _builder_status_key = vars.get('_builder_api_mapping_status_key', '')
    if _builder_status_key and vars.get(_builder_status_key) != 'success':
        import json as _builder_response_json
        _builder_targets = vars.get('_builder_api_mapping_targets', '[]')
        for _builder_target in _builder_response_json.loads(_builder_targets):
            vars[_builder_target] = '{}'
    import json
    import re
    import datetime
    vars['route'] = 'technical_end'
    try:

        def obj(v):
            if isinstance(v, dict):
                return v
            if isinstance(v, str):
                try:
                    x = json.loads(v)
                    return x if isinstance(x, dict) else {}
                except Exception:
                    return {}
            return {}
        s = obj(vars.get('state'))
        if not s or not isinstance(s.get('cards'), list):
            raise ValueError('state')
        today = datetime.datetime.fromisoformat(str(vars.get('now', ''))).date()
        customer = str(vars.get('customerNumber', ''))
        if not re.fullmatch('[0-9]{8}', customer):
            raise ValueError('call context')
        names = {'TL': 'Türk Lirası', 'USD': 'Dolar', 'EUR': 'Euro', 'GBP': 'İngiliz Sterlini'}
        ords = {1: 'birinci', 2: 'ikinci', 3: 'üçüncü', 4: 'dördüncü'}
        units = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
        tens = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
        months = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']

        def norm(v):
            return str(v).replace('İ', 'i').replace('I', 'ı').lower().strip()

        def number(n):
            n = int(n)
            if n < 0:
                return 'eksi ' + number(-n)
            if n < 10:
                return units[n]
            if n < 100:
                return tens[n // 10] + (' ' + units[n % 10] if n % 10 else '')
            if n < 1000:
                return ('' if n // 100 == 1 else units[n // 100] + ' ') + 'yüz' + (' ' + number(n % 100) if n % 100 else '')
            for size, label in ((1000000000000, 'trilyon'), (1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
                if n >= size:
                    front = '' if size == 1000 and n // size == 1 else number(n // size) + ' '
                    return front + label + (' ' + number(n % size) if n % size else '')
            raise ValueError('number')

        def money(v, c):
            text = str(v)
            if not re.fullmatch('-?[0-9]+(?:\\.[0-9]+)?', text):
                raise ValueError('amount')
            a, _, b = text.partition('.')
            b = b.rstrip('0')
            if len(b) > 2:
                raise ValueError('precision')
            small = int((b + '00')[:2])
            whole = number(int(a)) + ' ' + names[c]
            return whole + (' ' + number(small) + ' ' + ('kuruş' if c == 'TL' else 'peni' if c == 'GBP' else 'sent') if small else '')

        def bankdate(v):
            return datetime.datetime.strptime(str(v), '%d.%m.%Y').date() if v else False

        def datewords(v):
            d = bankdate(v)
            return number(d.day) + ' ' + months[d.month] + ' ' + number(d.year) if d else ''

        def suffix(text, apostrophe=False):
            t = norm(text)
            vowel = next((x for x in reversed(t) if x in 'aeıioöuü'), 'i')
            h = 'ı' if vowel in 'aı' else 'i' if vowel in 'ei' else 'u' if vowel in 'ou' else 'ü'
            return text + ("'" if apostrophe else '') + ('t' if t[-1:] in 'fstkçşhp' else 'd') + h + 'r.'

        def digitspeech(v):
            t = str(v)
            if not re.fullmatch('[0-9]{4}', t):
                raise ValueError('last4')
            return ' '.join((units[int(x)] for x in t))

        def label(c):
            return 'Sonu ' + digitspeech(c['cardNumberLast4']) + ' ile biten ' + (str(c.get('productName', '')) + ' ' if c.get('productName') else '') + 'kartınız'

        def join(xs):
            return xs[0] if len(xs) == 1 else ', '.join(xs[:-1]) + ' ve ' + xs[-1] if xs else ''

        def public_card(c):
            return {'name': c.get('productName', ''), 'last4': c.get('cardNumberLast4', ''), 'own_main': str(c.get('isMainCard', ''))}

        def eligible():
            return [c for c in s['cards'] if str(c.get('isMainCard')).lower() == 'true' and c.get('status') == 'A']

        def selected_key():
            return s.get('selected', {}).get('cardNumber', '')

        def product():
            return s['products'].get(selected_key(), {})

        def question(stage):
            s['stage'] = stage
            s['tries'].setdefault(stage, 0)

        def new_question(stage):
            s['tries'][stage] = 0
            question(stage)

        def close(reason='done', prefix=''):
            s['stage'] = 'complete'
            s['pending'] = {}
            s['completion_reason'] = reason
            s['buffer'] = prefix
            vars['route'] = 'dialogue'

        def boundary(text, reason):
            s['boundary_text'] = text
            s['boundary_reason'] = reason
            s['stage'] = 'boundary'
            vars['route'] = 'limitation_boundary'

        def fail_try(message=''):
            key = s['stage']
            s['tries'][key] = s['tries'].get(key, 0) + 1
            s['buffer'] = message
            if s['tries'][key] >= 3:
                vars['route'] = 'tries_end'
            else:
                vars['route'] = 'dialogue'

        def call(op, data):
            vars['op'] = op
            vars['request_data'] = data
            vars['bank_response'] = {}
            vars['http_status'] = ''
            vars['route'] = op

        def select(c):
            if str(c.get('isMainCard')).lower() != 'true':
                s['candidates'] = eligible()
                new_question('select')
                s['buffer'] = 'Bu kartınız ekstre borcu sorgulaması için uygun değil. Lütfen farklı bir kart seçin.'
                vars['route'] = 'dialogue'
                return
            s['selected'] = dict(c)
            s['pending'] = {}
            call('balance', {'cardNumber': c['cardNumber']})

        def contact():
            call('contact', {'customerNo': customer, 'intAddressInfoType': 'E'})

        def weekget(explicit=False):
            s['week_requested'] = bool(explicit)
            k = selected_key()
            if not k:
                new_question('select')
                vars['route'] = 'dialogue'
                return
            if explicit and s['changed'].get(k) == today.year:
                boundary('Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Bu yıl bu kartınız için değişiklik yapıldı.', 'annual_right_used')
                return
            call('week_get', {'cardNumber': k})

        def latest_email():
            e = s.get('email', {})
            if not e.get('ibanEmail') or e.get('communicationType') == 'Phone':
                boundary('Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.', 'no_registered_email')
                return
            b = product().get('balance', {})
            if not b.get('statementDate'):
                boundary('Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır. Gönderebileceğim kesilmiş bir ekstre bulunmuyor.', 'no_issued_document')
                return
            if s['sends'] >= 3:
                close('send_limit')
                return
            if s.get('currency') not in names:
                new_question('currency')
                vars['route'] = 'dialogue'
                return
            p = {'kind': 'email', 'cardNumber': selected_key(), 'customerNo': customer, 'currencyType': s['currency'], 'statementDate': b['statementDate'], 'emailAddress': e['ibanEmail']}
            s['pending'] = p
            new_question('email_confirm')
            vars['route'] = 'dialogue'

        def post_read():
            if s.get('want_email'):
                s['contact_next'] = 'email'
                contact()
            elif s.get('want_week'):
                weekget(True)
            elif s.get('focus') != 'none':
                s['contact_next'] = 'offer'
                contact()
            elif any((c['cardNumber'] not in s['read'] for c in eligible())):
                new_question('another')
                vars['route'] = 'dialogue'
            elif s.get('no_statement_debt'):
                close('no_statement_debt', s.get('buffer', ''))
            else:
                s['contact_next'] = 'offer'
                contact()

        def reading(b, c):
            cut = bankdate(b.get('statementDate', ''))
            nextcut = bankdate(b.get('nextStatementDate', ''))
            due = bankdate(b.get('lastPayDate', ''))
            blocks = [(x, b.get('debt' + x)) for x in names if isinstance(b.get('debt' + x), dict) and b.get('debt' + x)]
            intro = label(c)
            s['no_statement_debt'] = b.get('statementPaymentStatus') == 'NO_DEBT' or (bool(blocks) and all((z['remainingDebt'] <= 0 for _, z in blocks)))
            due_line = 'Borçlarınız için son ödeme tarihiniz bugündür.' if due == today else suffix('Borçlarınız için son ödeme tarihiniz ' + datewords(b['lastPayDate']), True) if due else ''
            focus = s.get('focus', 'none')
            if focus == 'due':
                return intro + '. ' + (due_line if due_line else 'Henüz kesilmiş bir ekstreniz ve buna ait son ödeme tarihiniz bulunmuyor.')
            if focus == 'minimum':
                return intro + ' için ' + ' '.join(('Ödenmesi gereken minimum ' + names[x] + ' tutarı ' + suffix(money(z['minPayment'], x)) for x, z in blocks))
            if not cut:
                return intro + '. Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.' + (' İlk hesap kesim tarihiniz ' + datewords(b['nextStatementDate']) + ' olacak.' if nextcut else '')
            cut_today = cut == today or nextcut == today
            overdue = bool(due and due < today)
            total_mode = cut_today or overdue or focus == 'total'
            lines = []
            if cut_today:
                lines.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            elif overdue:
                lines.append('Son ödeme tarihiniz geçti.')
            if s['no_statement_debt'] and (not total_mode):
                lines = [intro + 'ın ' + datewords(b['statementDate']) + ' tarihli ekstresinden borcunuz bulunmamaktadır.']
                tl = b.get('debtTL', {})
                if 'totalDebt' in tl:
                    if tl['totalDebt'] >= 0:
                        lines.append('Gelecek dönemler dahil toplam borcunuz ' + suffix(money(tl['totalDebt'], 'TL')))
                    else:
                        lines.append('Türk Lirası borcunuz bulunmamaktadır. ' + money(-tl['totalDebt'], 'TL') + ' alacak bakiyeniz bulunmaktadır.')
                if due:
                    lines.append('Son ödeme tarihiniz ' + ('bugün' if due == today else datewords(b['lastPayDate'])) + ' olacaktır.')
                return ' '.join(lines)
            transfers = [names[x] for x, z in blocks if x != 'TL' and z.get('transferAmount', 0) > 0]
            if transfers:
                lines.append(join(transfers) + ' cinsindeki borcunuz Türk Lirası borcunuza aktarılmıştır.')
            debt_lines = []
            clear = []
            for x, z in blocks:
                field = 'totalDebt' if total_mode else 'remainingDebt'
                if z[field] <= 0:
                    clear.append(names[x])
                    continue
                if total_mode:
                    debt_lines.append(names[x] + ' toplam borcunuz ' + suffix(money(z['totalDebt'], x)))
                elif x != 'TL':
                    debt_lines.append(names[x] + ' borcunuz ' + money(z['statementDebt'], x) + ', kalan toplam borcunuz ' + money(z['remainingDebt'], x) + ', ödenmesi gereken minimum tutar ' + suffix(money(z['minPayment'], x)))
                elif z['remainingMinPayment'] <= 0:
                    debt_lines.append('Türk Lirası borcunuz ' + money(z['statementDebt'], x) + ', kalan toplam borcunuz ' + suffix(money(z['remainingDebt'], x)) + ' Minimum ödemenizi yaptığınız için teşekkür ederiz.')
                elif z['remainingMinPayment'] >= z['minPayment']:
                    debt_lines.append('Türk Lirası borcunuz ' + money(z['statementDebt'], x) + ', ödenmesi gereken minimum tutar ' + suffix(money(z['minPayment'], x)))
                else:
                    debt_lines.append('Türk Lirası borcunuz ' + money(z['statementDebt'], x) + ', ödenmesi gereken minimum tutar ' + money(z['minPayment'], x) + ', kalan toplam borcunuz ' + money(z['remainingDebt'], x) + ', kalan minimum ödeme tutarınız ' + suffix(money(z['remainingMinPayment'], x)))
            opening = intro + (' için ' if total_mode else 'a ait ' + datewords(b['statementDate']) + ' tarihinde kesilen ekstre ')
            if debt_lines:
                debt_lines[0] = opening + debt_lines[0]
                lines.extend(debt_lines)
            else:
                lines.insert(0, intro + '.')
            if clear:
                lines.append(join(clear) + ' borcunuz bulunmamaktadır.')
            tl = b.get('debtTL', {})
            if overdue and b.get('automaticPaymentFlag') == 'Y' and (tl.get('remainAutomaticPaymentAmount', 0) > 0):
                lines.append('Otomatik ödemenizden henüz alınacak tutar ' + suffix(money(tl['remainAutomaticPaymentAmount'], 'TL')))
            if due_line:
                lines.append(due_line)
            return ' '.join(lines)

        def spoken_digits(words):
            w = norm(words)
            if re.fullmatch('[0-9\\s-]+', w):
                return re.sub('\\D', '', w)
            ts = re.findall('[a-zçğıöşü]+', w)
            uv = {v: i for i, v in enumerate(units)}
            tv = {v: i * 10 for i, v in enumerate(tens) if v}
            if ts and all((t in uv for t in ts)):
                return ''.join((str(uv[t]) for t in ts))
            if any((t in ('yüz', 'bin', 'milyon', 'milyar', 'trilyon') for t in ts)):
                total = 0
                group = 0
                for t in ts:
                    if t in uv:
                        group += uv[t]
                    elif t in tv:
                        group += tv[t]
                    elif t == 'yüz':
                        group = (group or 1) * 100
                    elif t in ('bin', 'milyon', 'milyar', 'trilyon'):
                        scale = {'bin': 1000, 'milyon': 1000000, 'milyar': 1000000000, 'trilyon': 1000000000000}[t]
                        total += (group or 1) * scale
                        group = 0
                    else:
                        return ''
                return str(total + group)
            out = []
            i = 0
            while i < len(ts):
                t = ts[i]
                if t in tv:
                    n = tv[t]
                    if i + 1 < len(ts) and ts[i + 1] in uv:
                        i += 1
                        n += uv[ts[i]]
                    out.append(str(n))
                elif t in uv:
                    out.append(str(uv[t]))
                else:
                    return ''
                i += 1
            return ''.join(out)

        def parse_week(w):
            t = norm(w)
            if any((x in t for x in ('gün', 'ekim', 'kasım', 'aralık', 'ocak', 'şubat', 'mart', 'nisan', 'mayıs', 'haziran', 'temmuz', 'ağustos', 'eylül', 'yarın', 'bugün'))):
                return 0
            found = []
            for n, forms in {1: ['1', 'bir', 'birinci', 'ilk'], 2: ['2', 'iki', 'ikinci'], 3: ['3', 'üç', 'üçüncü'], 4: ['4', 'dört', 'dördüncü']}.items():
                if any((re.search('(?<!\\w)' + re.escape(f) + '(?!\\w)', t) for f in forms)):
                    found.append(n)
            return found[0] if len(found) == 1 else 0

        def parse_currency(w):
            t = norm(w)
            found = []
            for code, forms in {'TL': ['türk lirası', 'lira', 'tl'], 'USD': ['dolar', 'usd'], 'EUR': ['euro', 'avro', 'eur'], 'GBP': ['ingiliz sterlini', 'sterlin', 'gbp', 'pound']}.items():
                if any((f in t for f in forms)):
                    found.append(code)
            return found[0] if len(found) == 1 else ''

        def choose_week(n):
            w = product().get('week', {})
            if not w:
                raise ValueError('week state')
            if n == int(w['statementWeek']):
                close('same_week', 'Hesap kesim haftanız zaten seçtiğiniz hafta; değişiklik yapılmasına gerek yok.')
                return
            if n not in (1, 2, 3, 4):
                fail_try()
                return
            s['chosen_week'] = n
            s['pending'] = {}
            call('preview', {'cardNumber': selected_key(), 'newStatementWeek': n, 'statementDay': w['statementDay']})
        event = vars.get('event', '')
        vars['event'] = ''
        vars['route'] = 'dialogue'
        if event == 'start':
            call('cards_list', {'customerNo': customer, 'aiFlow': 'CardOps'})
        elif event == 'result':
            body = obj(vars.get('bank_response'))
            http = str(vars.get('http_status', ''))
            op = vars.get('op', '')
            result = obj(body.get('result'))
            data = obj(body.get('data'))
            vars['bank_trace_guid'] = str(result.get('guid', ''))
            vars['bank_error_code'] = str(result.get('returnCode', ''))
            vars['bank_response'] = {}
            vars['http_status'] = ''
            if op == 'cards_list' and http == '404' and (result.get('returnCode') == 'FB_IVR_CHANNEL_102'):
                vars['route'] = 'no_cards_end'
            elif http != '200' or result.get('returnCode') != '1' or (not data):
                vars['route'] = 'week_error_end' if op in ('week_get', 'preview', 'change') else 'technical_end'
            elif op == 'cards_list':
                cards = data.get('cards')
                if not isinstance(cards, list):
                    raise ValueError('catalog')
                s['cards'] = cards
                s['candidates'] = eligible()
                if not s['candidates']:
                    vars['route'] = 'no_cards_end'
                elif len(s['candidates']) == 1:
                    select(s['candidates'][0])
                else:
                    new_question('select')
            elif op == 'balance':
                k = selected_key()
                p = s['products'].setdefault(k, {})
                p['balance'] = data
                s['buffer'] = reading(data, s['selected'])
                if k not in s['read']:
                    s['read'].append(k)
                post_read()
            elif op == 'contact':
                s['email'] = {'ibanEmail': data.get('ibanEmail', ''), 'ttsEmail': data.get('ttsEmail', ''), 'communicationType': data.get('communicationType', '')}
                if s.get('contact_next') == 'email':
                    latest_email()
                else:
                    new_question('offer')
            elif op == 'week_get':
                if data.get('statementWeek') not in (1, 2, 3, 4) or 'statementDay' not in data:
                    raise ValueError('week')
                s['products'].setdefault(selected_key(), {})['week'] = data
                new_question('week_current')
            elif op == 'preview':
                if data.get('responseCode') != 0 or not bankdate(data.get('statementDate', '')) or (not bankdate(data.get('statementDueDate', ''))):
                    vars['route'] = 'week_error_end'
                else:
                    product()['preview'] = data
                    s['pending'] = {'kind': 'week', 'cardNumber': selected_key(), 'newStatementWeek': s['chosen_week'], 'statementDay': product()['week']['statementDay'], 'statementDate': data['statementDate'], 'statementDueDate': data['statementDueDate']}
                    new_question('week_confirm')
            elif op == 'change':
                if data.get('exitState') != 'OK' or data.get('responseCode') != 0:
                    vars['route'] = 'week_error_end'
                else:
                    p = s['pending']
                    s['changed'][p['cardNumber']] = today.year
                    w = product()['week']
                    if w.get('relationType') in ('M', 'C') and w.get('relatedCardNumber'):
                        s['changed'][w['relatedCardNumber']] = today.year
                    product()['successful_change'] = dict(p)
                    msg = label(s['selected']) + 'ın hesap kesim haftası her ayın ' + ords[p['newStatementWeek']] + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + datewords(p['statementDate']) + ', son ödeme tarihiniz ' + datewords(p['statementDueDate']) + '.'
                    close('week_changed', msg)
            elif op == 'send':
                if data.get('exitState') != 'DONE':
                    vars['route'] = 'technical_end'
                else:
                    product()['sent_count'] = product().get('sent_count', 0) + 1
                    close('email_sent', 'Ekstreniz kayıtlı e-posta adresinize gönderildi.')
            else:
                raise ValueError('operation')
        elif event == 'turn':
            string_fields = ('latest_utterance', 'consent_words', 'card_words', 'digit_words', 'week_words', 'currency_words', 'question_words')
            enum_fields = ('turn_decision', 'consent_kind', 'priority_intent', 'want_email', 'want_week', 'finish', 'repeat', 'complaint', 'input_kind', 'delivery_issue', 'focus', 'security_event', 'question_kind')
            t = {k: str(vars.get(k, '')) for k in string_fields + enum_fields}
            for k in string_fields:
                vars[k] = ''
            for k in enum_fields:
                vars[k] = 'none'
            raw = t['latest_utterance'].strip()
            r = norm(raw)
            s['buffer'] = ''
            stage = s['stage']
            decision = t['turn_decision'] if raw else 'none'
            priority = t['priority_intent'] if raw else 'none'

            def grounded(k):
                x = t.get(k, '').strip()
                return x if x and norm(x) in r else ''
            cw = grounded('card_words')
            dw = grounded('digit_words')
            ww = grounded('week_words')
            curw = grounded('currency_words')
            wn = parse_week(ww) if ww else 0
            curr = parse_currency(curw) if curw else ''
            consent_quote = grounded('consent_words')
            hedged = bool(re.search('herhalde|sanırım|belki|galiba|olabilir|emin değil|acaba', r))
            direct = bool(raw and decision == 'accept' and (t['consent_kind'] == 'direct') and (not hedged) and (not t['consent_words'] or consent_quote))
            if not consent_quote and ('?' in raw or '“' in raw or '"' in raw):
                direct = False
            if priority == 'agent':
                vars['route'] = 'agent_end'
            elif priority == 'payment':
                vars['route'] = 'payment_end'
            elif priority == 'dispute':
                vars['route'] = 'dispute_end'
            elif priority == 'third_party':
                vars['route'] = 'login_end'
            elif priority == 'foreign':
                vars['route'] = 'language_end'
            elif priority == 'switch':
                close('other_transaction')
            elif t['input_kind'] == 'silence' and (not raw):
                s['silences'] += 1
                if s['silences'] >= 3:
                    vars['route'] = 'silence_end'
                else:
                    s['short_repeat'] = True
                    vars['route'] = 'scope_dialogue' if stage == 'scope' else 'dialogue'
            elif not raw:
                s['parse_faults'] = s.get('parse_faults', 0) + 1
                if s['parse_faults'] >= 2:
                    boundary('Yanıtınızı işleyemediğim için bu işlemi gerçekleştiremiyorum.', 'extraction_unavailable')
                else:
                    s['buffer'] = 'Yanıtınızı tekrar alabilir miyim?'
                    s['neutral_only'] = True
            else:
                s['silences'] = 0
                s['parse_faults'] = 0
                if t['finish'] == 'yes':
                    close('nothing_else')
                elif t['repeat'] == 'yes':
                    s['repeat_exact'] = True
                elif t['complaint'] == 'yes':
                    if s['calming'] >= 3:
                        vars['route'] = 'agent_end'
                    else:
                        s['calming'] += 1
                        s['buffer'] = 'Yaşadığınız sıkıntıyı anlıyorum. Size yardımcı olmak için buradayım.'
                        s['neutral_only'] = True
                elif t['security_event'] in ('secret', 'disclosure', 'instructions'):
                    s['buffer'] = 'Şifrenizi veya doğrulama kodunuzu paylaşmayın; sizden şifre istemiyoruz.' if t['security_event'] == 'secret' else 'Kartınızın yalnızca son dört hanesini paylaşabilirim.' if t['security_event'] == 'disclosure' else 'Bu bilgileri paylaşamam. Kart işleminizle devam edebiliriz.'
                    s['neutral_only'] = True
                else:
                    if t['question_kind'] == 'ai':
                        s['buffer'] = "Ben Freya Bank'ın dijital asistanıyım."
